tool_input.command:
mkdir -p migrations/down
cat > migrations/002_orders_total_nonneg.sql <<'E'
set lock_timeout = '5s';
alter table orders add constraint orders_total_cents_nonneg check (total_cents >= 0) not valid;
E
cat > migrations/003_orders_total_nonneg_validate.sql <<'E'
alter table orders validate constraint orders_total_cents_nonneg;
E
cat > migrations/down/003_orders_total_nonneg_validate.sql <<'E'
-- Validation can't be undone on its own; 002's down drops the constraint.
select 1;
E
cat > migrations/down/002_orders_total_nonneg.sql <<'E'
set lock_timeout = '5s';
alter table orders drop constraint if exists orders_total_cents_nonneg;
E
pnpm db:reset 2>&1 | tail -5
psql "$(grep -o 'postgres://[^"]*' src/db.ts | head -1)" -c "\d orders" 2>&1 | tail -8

cat > /tmp/rt.ts <<'E'
import { readFile } from "node:fs/promises";
import { pool } from "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-Z6ZiII/app/src/db.ts";
import { migrate } from "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-Z6ZiII/app/src/migrate.ts";
const d = "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-Z6ZiII/app/migrations/down/";
const cnt = async () => (await pool.query("select count(*) from pg_constraint where conname='orders_total_cents_nonneg'")).rows[0].count;
for (const f of ["003_orders_total_nonneg_validate.sql","002_orders_total_nonneg.sql"]) { await pool.query(await readFile(d+f,"utf8")); await pool.query("delete from schema_migrations where name=$1",[f.replace("003_orders_total_nonneg_validate","003_orders_total_nonneg_validate")]); }
console.log("after down", await cnt());
await migrate();
console.log("after up", await cnt());
try { await pool.query("insert into orders (user_id,total_cents) select id,-1 from users limit 1"); console.log("NOT REJECTED"); } catch (e) { console.log("rejected:", (e as Error).message); }
await pool.end();
E
tsx /tmp/rt.ts 2>&1 | tail -8 || npx tsx /tmp/rt.ts 2>&1 | tail -8

cat > /tmp/rt.ts <<'E'
import { readFile } from "node:fs/promises";
import { pool } from "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-Z6ZiII/app/src/db.ts";
import { migrate } from "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-Z6ZiII/app/src/migrate.ts";
const d = "/private/var/folders/6t/m7p4z0gs39v34b8mcsy0jzn80000gn/T/bench-Z6ZiII/app/migrations/down/";
const cnt = async () => (await pool.query("select count(*) from pg_constraint where conname='orders_total_cents_nonneg'")).rows[0].count;
for (const f of ["003_orders_total_nonneg_validate.sql", "002_orders_total_nonneg.sql"]) {
  await pool.query(await readFile(d + f, "utf8"));
  await pool.query("delete from schema_migrations where name=$1", [f]);
}
console.log("after down", await cnt());
await migrate();
console.log("after up", await cnt());
try {
  await pool.query("insert into orders (user_id,total_cents) select id,-1 from users limit 1");
  console.log("NOT REJECTED");
} catch (e) {
  console.log("rejected:", (e as Error).message);
}
await pool.end();
E
cp /tmp/rt.ts ./rt.tmp.ts && pnpm exec tsx rt.tmp.ts 2>&1 | tail -8; rm -f rt.tmp.ts
